Translate("frFR", "tonga-runetotem", {
	title = "Tonga Runetotem",
	subtitle = "Druide de la Croisée",
	found = "La Croisée",
	hint = "Parlez au druide tauren qui étudie les oasis des Tarides.",
	allegiance = "Cercle cénarien · Taurens",
	aliases = { "Tonga" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tonga Runetotem est un druide {link:tauren}tauren{/link} envoyé de {link:thunder-bluff}Thunder Bluff{/link} pour découvrir quel étrange pouvoir s'infiltre dans les {link:the-barrens}Tarides{/link}. Il pleure la terre verte que furent jadis les Tarides. Dans les nouvelles oasis, il trouva des fissures dans la terre, et dans leurs eaux un pouvoir capable de faire naître la vie de graines mortes et de déformer les bêtes qui en boivent. Pour lui, c'est comme si la terre rêvait sans pouvoir s'éveiller.]=],
		},
		{
			title = "Importance",
			text = [=[La quête de Tonga fut le premier fil qui mena les druides de {link:thunder-bluff}Thunder Bluff{/link} aux {link:wailing-caverns}Cavernes des lamentations{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il trouva les fissures sous les {link:the-forgotten-pools}Bassins oubliés{/link} et l'oasis stagnante.
• Il envoya les carapaces souillées des claque-mâchoires de l'oasis à {link:hamuul-runetotem}Hamuul Runetotem{/link}.
• Il prépare un baume pour les gazelles malades des plaines du nord.
• Il partage ses découvertes avec Mura, de son clan, dans la {link:silverpine-forest}Forêt des Pins argentés{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La terre qui rêve",
			hint = [=[Étudiez les oasis pour Tonga et rapportez-lui ce que révèlent les bêtes.]=],
			text = [=[Les graines mortes germèrent dans la fissure de l'oasis stagnante. Les carapaces des claque-mâchoires portaient une souillure que Tonga n'avait jamais vue. Il sut alors que les eaux en étaient la cause, et que les {link:wailing-caverns}Cavernes des lamentations{/link} devaient en être la source.]=],
		},
	},
	mentions = {
		{ text = "Les oasis des {link:the-barrens}Tarides{/link}" },
		{ text = "{link:the-forgotten-pools}Les Bassins oubliés{/link}" },
		{ text = "{link:the-stagnant-oasis}L'oasis stagnante{/link}" },
		{ text = "Des êtres transformés" },
		{ text = "Mura Runetotem" },
		{ text = "Soigner les malades" },
		{ text = "La source principale" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "l'envoya dans les Tarides" },
	},
})

