	hint = [=[Cherchez le brasseur orc qui garde une vieille recette pandarène.]=],
	allegiance = "Horde",
	aliases = { "Drohn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître brasseur Drohn est un brasseur qui garde de vieilles recettes. Son mentor les apprit de Chen Stormstout, un brasseur vagabond qui voyagea jadis avec {link:rexxar}Rexxar{/link}, et les lui transmit. Quand l'un des fûts vides de Chen fit surface dans les {link:the-barrens}Tarides{/link}, Drohn n'avait pas entendu parler de Chen depuis une éternité de kodo. Cela réveilla ses souvenirs, et il brassa de nouveau la stormstout.]=],
		},
		{
