		},
	},
	mentions = {
		{ text = "Le fût vide de Chen" },
		{ text = "Le fût vide de Chen, la stormstout" },
		{ text = "Le fût vide de Chen, l'ale de {link:troggs}trogg{/link}" },
	},
})

Translate("frFR", "gann-stonespire", {
	title = "Gann Stonespire",
	subtitle = "Dernier des Stonespire",
	found = "La route au nord de Bael Modan",
	hint = [=[Cherchez le tauren qui erre seul sur les routes près de Bael Modan.]=],
	allegiance = "Tribu Stonespire · Taurens",
	aliases = { "Gann" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gann Stonespire erre seul sur les routes du sud des {link:the-barrens}Tarides{/link}. La terre où les nains creusent aujourd'hui à {link:bael-modan}Bael Modan{/link} était le foyer et la nourricière de sa tribu. Leurs explosions y percent des trous et leurs machines la déchirent. Gann tenta de parvenir à un accord pacifique avec eux et échoua. Désormais, il cherche leurs journaux, leurs explosifs et la ruine de leur machine volante.]=],
		},
		{
			title = "Importance",
			text = [=[Gann est la voix d'une tribu qui a perdu sa terre. Il demande que ceux qui combattent pour lui soient honorés à {link:thunder-bluff}Thunder Bluff{/link} comme défenseurs de la terre sacrée des taurens.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tenta en vain de faire la paix avec les nains de {link:bael-modan}Bael Modan{/link}.
• Il fabriqua une charge explosive d'après les plans des nains eux-mêmes.]=],
		},
	},
	chapters = {
		{
			title = "La vengeance de Gann",
			hint = "Détruisez la machine volante de Bael Modan pour Gann.",
			text = [=[Pour Gann, la machine volante des nains était plus qu'un instrument de guerre. C'était une insulte à la mémoire de sa tribu. Il construisit une charge d'après le journal du prospecteur des nains, et il la confia à qui la porterait jusqu'à la machine.]=],
		},
	},
	mentions = {
		{ text = "La reconquête de Gann" },
		{ text = "La vengeance de Gann" },
	},
})

Translate("frFR", "walton", {
	title = "Walton",
	subtitle = "Le tanneur ermite",
	found = "Une crête au-dessus des Collines arides",
	hint = [=[Montez jusqu'à l'ermite qui vit sur la crête au-dessus des Collines arides.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Walton est un tanneur qui vit seul sur une crête au-dessus des {link:the-dry-hills}Collines arides{/link}. Il échange des peaux avec le chasseur {link:vrang-wildgore}Vrang Wildgore{/link}, qui prévient les visiteurs de ne pas s'alarmer de son apparence. Walton fut autrefois marin dans la flotte de {link:kul-tiras}Kul Tiras{/link}. Quand {link:daelin-proudmoore}Daelin Proudmoore{/link} fit la guerre à la {link:horde}Horde{/link}, Walton s'opposa aux méthodes de l'amiral, surtout au massacre de civils. Son histoire ne s'arrête pas là, dit-il, et il ne la raconte pas tout entière.]=],
		},
		{
			title = "Importance",
			text = [=[Walton est la preuve que tous les Kultirassiens ne suivirent pas l'amiral de leur plein gré. Les hommes qui arborent encore la bannière de {link:daelin-proudmoore}Daelin{/link} ne l'ont pas oublié.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il quitta le service de l'amiral à cause du massacre de civils.
• Il tanne les peaux que lui apporte {link:vrang-wildgore}Vrang Wildgore{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Des hôtes importuns",
			hint = [=[Tenez bon aux côtés de l'ermite quand des étrangers gravissent la crête.]=],
			text = [=[Une bande d'hommes monta sur la crête : un chasseur de primes nommé Terry Longdrink et des soldats de marine de {link:kul-tiras}Kul Tiras{/link}. Ils étaient venus pour Walton. Quand le combat fut terminé et qu'il était encore en vie, il dit qu'il avait toujours su que cela le rattraperait un jour.]=],
		},
		{
			title = "Du grabuge dans la vallée",
			hint = [=[Découvrez pourquoi des soldats kultirassiens campent près de la caravane détruite.]=],
			text = [=[Walton avait vu des hommes à la livrée de {link:kul-tiras}Kul Tiras{/link} fouiller la vallée en contrebas. Les ordres trouvés dans leur camp venaient du lieutenant {link:lieutenant-benedict}Benedict{/link}, du {link:tiragarde-keep}Donjon de Tiragarde{/link}. Ils traquaient un déserteur. Le passé, dit Walton, avait fini par le rattraper.]=],
		},
	},
	mentions = {
		{ text = "Le tanneur ermite" },
	},
	bonds = {
		{ id = "vrang-wildgore", name = "Vrang Wildgore", note = "échange des peaux avec lui" },
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "l'amiral qu'il défia" },
		{ id = "lieutenant-benedict", name = "Lieutenant Benedict", note = "envoya des hommes le trouver" },
	},
})

Translate("frFR", "vrang-wildgore", {
	title = "Vrang Wildgore",
	subtitle = "Trappeur des Collines arides",
	found = "La vallée en contrebas des Collines arides",
	hint = [=[Parlez au chasseur blessé qui tend des pièges dans la vallée en contrebas des Collines arides.]=],
	allegiance = "Horde",
	aliases = { "Vrang" },
	sections = {
		{
			title = "Résumé",
			text = [=[Vrang Wildgore est un chasseur et trappeur du nord des {link:the-barrens}Tarides{/link}. Une blessure récente à la jambe l'empêche de chasser et de grimper, et il lui en coûte dans son orgueil de demander de l'aide à des inconnus. Pourtant, il a des obligations à tenir. Il échange des peaux de lion brutes avec un tanneur qui vit sur la crête au-dessus de lui, et reçoit en retour le cuir fini de son métier.]=],
		},
		{
			title = "Importance",
			text = [=[Vrang est le seul ami de l'ermite {link:walton}Walton{/link}, et il se porte garant de lui auprès de quiconque le demande.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il récolte les peaux des grands lions de la savane.
• Il tend des pièges dans toute la vallée en contrebas des {link:the-dry-hills}Collines arides{/link}.]=],
		},
	},
	mentions = {
		{ text = "Orgueil blessé et peaux de lion" },
		{ text = "Le tanneur ermite" },
		{ text = "Le gibier de Vrang" },
	},
	bonds = {
		{ id = "walton", name = "Walton", note = "son partenaire d'échange" },
	},
})

Translate("frFR", "chol-aruk", {
	title = "Chol'aruk",
	subtitle = "Le Dévoreur",
	found = "Une grotte sur le plateau de la colline des Épines",
	hint = [=[Cherchez l'antre de la bête que les Tranchecrin appellent le Dévoreur.]=],
	allegiance = "Hurans Tranchecrin",
	aliases = { "Le Dévoreur" },
	sections = {
		{
			title = "Résumé",
			text = [=[Chol'aruk est un {link:quilboar}huran{/link} monstrueux qui a fait son antre dans une grotte de la colline des Épines. Les {link:razormane-quilboar}Tranchecrin{/link} l'appellent le Dévoreur. Ceux qui l'ont vu disent qu'il est cinq fois plus grand qu'un huran ordinaire, que sa soif de sang n'est jamais apaisée et qu'il pourrait avaler un {link:orcs}orc{/link} tout entier. La plupart des gens ne croient pas à ces récits. Gur'ak, de la {link:the-crossroads}Croisée{/link}, y croit, et Bainham aussi, un soldat de l'{link:alliance}Alliance{/link} à {link:ratchet}Ratchet{/link}. Chacun d'eux a déjà combattu une bête semblable, et chacun y a perdu des compagnons.]=],
		},
		{
			title = "Importance",
			text = [=[Chol'aruk est un sombre présage. Si de telles abominations venaient à marcher en plus grand nombre parmi les hurans, le mal qu'elles pourraient faire à la terre serait terrible.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il a son antre dans les profondeurs de la colline des Épines.]=],
		},
	},
	mentions = {
		{ text = "Chol'aruk le Dévoreur, pour Gur'ak" },
		{ text = "Chol'aruk le Dévoreur, pour Bainham" },
	},
})

Translate("frFR", "kolkar-centaurs", {
	title = "Centaures kolkar",
	aliases = { "Kolkar", "centaures kolkar", "tribu kolkar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Kolkar sont une tribu de {link:centaurs}centaures{/link} qui parcourt les {link:the-barrens}Tarides{/link} et les terres alentour. Leurs cavaliers campent près des oasis, chassent les bêtes qui viennent boire et s'abattent sur les voyageurs des routes. Ils pillèrent les taurens pendant des années avant la venue des orcs, et ils pillent la {link:horde}Horde{/link} depuis.]=],
		},
		{
			title = "En ces jours",
			text = [=[Longtemps, les Kolkar des {link:the-barrens}Tarides{/link} furent dispersés et désordonnés. Aujourd'hui, de nouveaux chefs se sont levés parmi eux : {link:barak-kodobane}Barak Kodobane{/link} près des {link:the-forgotten-pools}Bassins oubliés{/link}, {link:verog-the-dervish}Verog le Derviche{/link} à l'oasis stagnante, et {link:hezrul-bloodmark}Hezrul Bloodmark{/link}, le plus grand d'entre eux, à l'{link:lushwater-oasis}Oasis luxuriante{/link}. Sous ces chefs, la tribu est devenue une vraie menace. {link:regthar-deathgate}Regthar Deathgate{/link} les traque depuis ses bunkers à l'ouest de la {link:the-crossroads}Croisée{/link}, et quand leurs chefs tombèrent, une bande de guerre vint de la patrie des Kolkar, en {link:desolace}Désolace{/link}, pour se venger. En {link:durotar}Durotar{/link}, une autre bande tient la gorge rocheuse de la {link:kolkar-crag}Combe des Kolkar{/link}.]=],
		},
	},
})

Translate("frFR", "razormane-quilboar", {
	title = "Hurans Tranchecrin",
	aliases = { "Tranchecrin", "tribu Tranchecrin", "hurans Tranchecrin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Tranchecrin sont une tribu de {link:quilboar}hurans{/link} du nord et du sud des {link:the-barrens}Tarides{/link}. Ils dressent leurs camps parmi de grandes lianes épineuses qui sortent de la terre, et ils vénèrent l'esprit sanglier Agamaggan, dont le sang aurait, dit-on, fait naître les épines. Avant la venue des orcs, ils parcouraient la terre qui est aujourd'hui {link:durotar}Durotar{/link}, et ils n'ont jamais accepté de la perdre.]=],
		},
		{
			title = "En ces jours",
			text = [=[Les Tranchecrin sont en guerre contre la {link:horde}Horde{/link} et contre leurs cousins de la tribu {link:bristleback-quilboar}Dos-hirsute{/link}. Ils tiennent la colline des Épines à l'est de la {link:the-crossroads}Croisée{/link}, {link:bramblescar}Ronceplaie{/link} au milieu des plaines et la crête de Noirépine au sud. Leurs raids contre les caravanes de {link:durotar}Durotar{/link} étaient menés par trois des leurs sortis du {link:razorfen-kraul}Kraal de Tranchebauge{/link} : {link:nak}Nak{/link}, Kuz et {link:lok-orcbane}Lok Orcbane{/link}. Le forgeron du camp {link:camp-taurajo}Taurajo{/link} a découvert que leurs armes deviennent plus solides. Dans une grotte de la colline des Épines, les Tranchecrin parlent d'une bête monstrueuse de leur propre sang, le Dévoreur.]=],
		},
	},
})
